python3 -c $'import sys,json\nS=json.loads(sys.argv[1]) if len(sys.argv)>1 else {"rules":[[0,"1",1,"1","R"],[1,"_",2,"_","N"]],"tape":"1"}\ndef G(b):\n n=1\n for v in b:n=n*257+v+1\n return n\ndef D(n):\n a=[]\n while n>1:\n  n,r=divmod(n,257)\n  if not r:raise ValueError("invalid code")\n  a.append(r-1)\n return bytes(a[::-1])\ndef run(p,limit):\n rules={(s,c):(t,v,m) for s,c,t,v,m in p["rules"]};t={i:c for i,c in enumerate(p.get("tape","")) if c!="_"};h=p.get("head",0);s=p.get("start",0);trace=[]\n for k in range(limit):\n  c=t.get(h,"_");trace.append([s,h,c]);r=rules.get((s,c))\n  if r is None:return {"status":"HALT","steps":k,"state":s,"tape":sorted(t.items()),"trace":trace}\n  s,v,m=r\n  if v=="_":t.pop(h,None)\n  else:t[h]=v\n  h+={"L":-1,"R":1,"N":0}[m]\n return {"status":"LIMIT","steps":limit,"state":s,"tape":sorted(t.items()),"trace":trace}\nb=json.dumps(S,sort_keys=True,separators=(",",":"),ensure_ascii=False).encode();z=G(b);assert D(z)==b\nr=run(S,int(sys.argv[2]) if len(sys.argv)>2 else 20)\nprint(json.dumps({"machine":"Three-Cat-Cookies-Universal-Pocket","godel_digits":len(str(z)),"encoding_ok":True,"result":r,"actuality":"UNPROVEN"},ensure_ascii=False,separators=(",",":")))' "$@"
